import { useState, useRef, useEffect } from 'react';
import axios from 'axios';

export default function Chat({ API }) {
  const [messages, setMessages] = useState([
    { role: 'bot', text: "Hello! I'm ARIA. Ask me anything about your documents!" }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const logRef = useRef(null);

  useEffect(() => {
    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [messages]);

  const send = async () => {
    const q = input.trim();
    if (!q || loading) return;
    setInput('');
    setMessages(m => [...m, { role: 'user', text: q }]);
    setLoading(true);
    try {
      const { data } = await axios.post(`${API}/chat`, { question: q, user_id: 'user_001' });
      setMessages(m => [...m, { role: 'bot', text: data.answer, meta: `📎 ${data.sources?.join(', ') || 'general'} · ${Math.round((data.confidence || 0) * 100)}% confidence` }]);
    } catch {
      setMessages(m => [...m, { role: 'bot', text: '❌ Could not reach backend. Is FastAPI running on port 8000?' }]);
    }
    setLoading(false);
  };

  const now = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '240px 1fr', gap: 14, height: 'calc(100vh - 92px)' }}>
      {/* Sidebar */}
      <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <div style={{ padding: 12, borderBottom: '1px solid var(--border)' }}>
          <input placeholder="🔍 Search..." style={{ width: '100%', background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 7, padding: '7px 10px', color: 'var(--text)', fontSize: '0.75rem', outline: 'none', fontFamily: 'var(--sans)' }} />
        </div>
        <div style={{ flex: 1, overflowY: 'auto', padding: 8 }}>
          {['user_001', 'user_042', 'user_017', 'user_008'].map((u, i) => (
            <div key={u} style={{ padding: '10px', borderRadius: 8, cursor: 'pointer', marginBottom: 3, background: i === 0 ? 'rgba(59,130,246,0.1)' : 'transparent', border: `1px solid ${i === 0 ? 'rgba(59,130,246,0.2)' : 'transparent'}` }}>
              <div style={{ fontSize: '0.78rem', fontWeight: 500, color: 'var(--text)', marginBottom: 3 }}>{u}</div>
              <div style={{ fontSize: '0.65rem', color: 'var(--text3)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {['What are the alloy...', 'Summarize the doc...', 'Generate an image...', 'How does RAG work?'][i]}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Chat Main */}
      <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        {/* Header */}
        <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{ width: 32, height: 32, borderRadius: '50%', background: 'rgba(59,130,246,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.85rem' }}>🤖</div>
          <div>
            <div style={{ fontSize: '0.82rem', fontWeight: 600 }}>ARIA Assistant</div>
            <div style={{ fontSize: '0.6rem', color: 'var(--green)' }}>● Online · RAG Ready</div>
          </div>
        </div>

        {/* Messages */}
        <div ref={logRef} style={{ flex: 1, overflowY: 'auto', padding: 16, display: 'flex', flexDirection: 'column', gap: 12 }}>
          {messages.map((m, i) => (
            <div key={i} style={{ display: 'flex', gap: 8, alignItems: 'flex-end', flexDirection: m.role === 'user' ? 'row-reverse' : 'row' }}>
              <div style={{ width: 26, height: 26, borderRadius: '50%', background: m.role === 'user' ? 'rgba(139,92,246,0.15)' : 'rgba(59,130,246,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.7rem', flexShrink: 0 }}>
                {m.role === 'user' ? 'KB' : '🤖'}
              </div>
              <div>
                <div style={{
                  maxWidth: 420, padding: '9px 13px', borderRadius: 12, fontSize: '0.78rem', lineHeight: 1.5,
                  background: m.role === 'user' ? 'linear-gradient(135deg, rgba(59,130,246,0.3), rgba(6,182,212,0.2))' : 'var(--surface2)',
                  border: `1px solid ${m.role === 'user' ? 'rgba(59,130,246,0.3)' : 'var(--border)'}`,
                  borderBottomRightRadius: m.role === 'user' ? 3 : 12,
                  borderBottomLeftRadius: m.role === 'bot' ? 3 : 12,
                  color: 'var(--text)'
                }}>{m.text}</div>
                {m.meta && <div style={{ fontSize: '0.55rem', color: 'var(--text3)', marginTop: 3, fontFamily: 'var(--mono)' }}>{m.meta}</div>}
                <div style={{ fontSize: '0.55rem', color: 'var(--text3)', marginTop: 2, fontFamily: 'var(--mono)', textAlign: m.role === 'user' ? 'right' : 'left' }}>{now}</div>
              </div>
            </div>
          ))}
          {loading && (
            <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end' }}>
              <div style={{ width: 26, height: 26, borderRadius: '50%', background: 'rgba(59,130,246,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.7rem' }}>🤖</div>
              <div style={{ display: 'flex', gap: 3, padding: '10px 14px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: '12px 12px 12px 3px' }}>
                {[0, 1, 2].map(i => <div key={i} style={{ width: 5, height: 5, borderRadius: '50%', background: 'var(--text3)', animation: `typingBounce 1.2s ${i * 0.2}s infinite` }} />)}
              </div>
            </div>
          )}
        </div>

        {/* Input */}
        <div style={{ padding: 12, borderTop: '1px solid var(--border)', display: 'flex', gap: 8 }}>
          <input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && send()}
            placeholder="Ask ARIA anything..."
            style={{ flex: 1, background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 8, padding: '9px 14px', color: 'var(--text)', fontFamily: 'var(--sans)', fontSize: '0.8rem', outline: 'none' }} />
          <button onClick={send} disabled={loading} style={{ padding: '9px 16px', borderRadius: 8, border: 'none', background: 'linear-gradient(135deg, #3b82f6, #06b6d4)', color: '#fff', fontSize: '0.8rem', cursor: 'pointer', fontWeight: 600, fontFamily: 'var(--sans)' }}>
            Send ↗
          </button>
        </div>
      </div>
    </div>
  );
}
